    image_patch = ImagePatch(image)
    wood_patches = image_patch.find("wood")
    bread_patches = image_patch.find("bread")

    if not wood_patches or not bread_patches:
        return image_patch

    wood_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in wood_patches]
    bread_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in bread_patches]

    for wood_center in wood_centers:
        for bread_center in bread_centers:
            if wood_center[1] < bread_center[1]:  # Wood is above bread
                return image_patch

    return image_patch

